"""Reproducible analysis pipeline generated by Avaloka.

Mission goal: Predict 'depth_may_next'
This script reproduces the data preparation performed during the Avaloka
mission. It is dependency-light (pandas only) and deterministic.
"""

import pandas as pd

DATA_SOURCE = 'C:\\Users\\Hrishi\\Desktop\\projects\\Gujarat Monsoon gap\\data\\processed\\gujarat_groundwater_model_features.csv'


# The strings read as missing, per column, exactly as the analysis read them.
MISSING_STRINGS = {
    **dict.fromkeys(['station_code', 'station_name', 'district', 'hydro_zone'], ['']),
    **dict.fromkeys(['latitude', 'longitude', 'year', 'depth_may', 'depth_nov', 'recharge_delta', 'recharge_gap_flag', 'relative_recovery_ratio', 'depth_jan_next', 'rabi_drawdown', 'depth_may_next', 'stress_alarm_next', 'trailing_depth_mean_3yr', 'baseline_persistence_pred', 'baseline_persistence_abs_err'], ['', '#N/A', '#N/A N/A', '#NA', '-1.#IND', '-1.#QNAN', '-NaN', '-nan', '1.#IND', '1.#QNAN', '<NA>', 'N/A', 'NA', 'NULL', 'NaN', 'None', 'n/a', 'nan', 'null']),
}


def load() -> pd.DataFrame:
    df = pd.read_csv(
        DATA_SOURCE, sep=',', encoding='utf-8', keep_default_na=False, na_values=MISSING_STRINGS)
    return df.dropna(axis=1, how="all")  # all-empty columns, as the analysis dropped them

def transform(df: pd.DataFrame) -> pd.DataFrame:
    """Apply the transformations Avaloka selected for this dataset."""
    for _c in ['station_code', 'station_name', 'district', 'hydro_zone']:
        df[_c] = df[_c].astype('string').str.strip()
    return df


def main() -> None:
    df = load()
    print("Loaded:", df.shape)
    df = transform(df)
    print("Transformed:", df.shape)
    df.to_parquet("transformed_dataset.parquet", index=False)
    print("Wrote transformed_dataset.parquet")


if __name__ == "__main__":
    main()
